<?php
require_once dirname(__DIR__).'/app/helpers.php';
require_once dirname(__DIR__).'/app/database.php';
$token=preg_replace('/[^a-f0-9]/','',(string)($_GET['token']??''));
$playKey=trim((string)($_GET['play']??''));
if($playKey!==''){$st=db()->prepare("SELECT t.token FROM embed_tokens t WHERE t.play_key=? AND t.status=1 LIMIT 1");$st->execute([$playKey]);$token=(string)($st->fetchColumn()?:'');}
if(!preg_match('/^[a-f0-9]{64}$/',$token)){http_response_code(404);exit('Invalid player token');}
$st=db()->prepare("SELECT v.*,t.id token_id,t.play_key FROM embed_tokens t JOIN videos v ON v.id=t.video_id WHERE t.token=? AND t.status=1 AND (t.expires_at IS NULL OR t.expires_at>NOW()) AND v.status='published' LIMIT 1");$st->execute([$token]);$v=$st->fetch();if(!$v){http_response_code(404);exit('Video unavailable');}
$ref=$_SERVER['HTTP_REFERER']??'';$host=strtolower(parse_url($ref,PHP_URL_HOST)?:'');
if($host){$ok=db()->prepare("SELECT id FROM allowed_domains WHERE status=1 AND (domain=? OR ? LIKE CONCAT('%.',domain)) LIMIT 1");$ok->execute([$host,$host]);if(!$ok->fetch()){http_response_code(403);exit('Embedding domain not allowed');}}
$ls=db()->prepare('SELECT id,label,url,requests,status FROM stream_links WHERE video_id=? AND status=1 ORDER BY sort_order,id');$ls->execute([$v['id']]);$streams=$ls->fetchAll();if(!$streams){http_response_code(404);exit('No active player source');}
db()->prepare('UPDATE videos SET views=views+1 WHERE id=?')->execute([$v['id']]);
$playColor='#2F80ED';$pc=db()->prepare("SELECT setting_value FROM settings WHERE setting_key='PLAYER_PLAY_COLOR'");$pc->execute();$pv=$pc->fetchColumn();if($pv && preg_match('/^#[0-9A-Fa-f]{6}$/',$pv))$playColor=$pv;
$timeout=8000;$pt=db()->prepare("SELECT setting_value FROM settings WHERE setting_key='PLAYER_FAILOVER_TIMEOUT'");$pt->execute();$tv=(int)$pt->fetchColumn();if($tv>=3000&&$tv<=30000)$timeout=$tv;
$hostData=[];foreach($streams as $s)$hostData[]=['id'=>(int)$s['id'],'label'=>$s['label'],'url'=>$s['url']];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="origin-when-cross-origin"><title><?=e($v['title'])?></title><style>:root{color-scheme:dark;--play:<?=e($playColor)?>}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:#000;font-family:system-ui,-apple-system,"Segoe UI",sans-serif;overflow:hidden}.player{position:relative;width:100%;height:100%;background:#000}.frame{width:100%;height:100%;border:0;display:block;background:#000}.loading{position:absolute;inset:0;z-index:5;display:grid;place-items:center;background:#000b;color:#dbeafe}.loading-box{text-align:center}.spinner{width:34px;height:34px;margin:0 auto 12px;border:4px solid #334155;border-top-color:#93c5fd;border-radius:50%;animation:spin .9s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.play-overlay{position:absolute;z-index:6;inset:0;display:grid;place-items:center;background:#0006;cursor:pointer}.play-button{width:82px;height:82px;border-radius:50%;border:0;background:var(--play);color:#fff;display:grid;place-items:center;box-shadow:0 12px 35px #0008;cursor:pointer}.play-button:before{content:"";width:0;height:0;border-top:13px solid transparent;border-bottom:13px solid transparent;border-left:20px solid #fff;margin-left:5px}.host-error{position:absolute;left:16px;right:16px;bottom:16px;z-index:7;padding:10px 14px;border-radius:8px;background:#3b0d0dcc;color:#fecaca;font-size:12px;display:none}.retry{margin-left:8px;background:#7f1d1d;border:1px solid #ef4444;color:#fff;padding:5px 8px;border-radius:5px;cursor:pointer}.hidden{display:none!important}</style></head><body><div class="player"><iframe id="host-frame" class="frame" src="<?=e($streams[0]['url'])?>" allow="autoplay; fullscreen; picture-in-picture; encrypted-media" allowfullscreen referrerpolicy="origin-when-cross-origin"></iframe><div id="loading" class="loading"><div class="loading-box"><div class="spinner"></div><div>Checking player host…</div></div></div><div id="play-overlay" class="play-overlay"><button id="play-button" class="play-button" aria-label="Play"></button></div><div id="host-error" class="host-error"></div></div><script>(function(){const hosts=<?=json_encode($hostData,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?>,frame=document.getElementById('host-frame'),loading=document.getElementById('loading'),overlay=document.getElementById('play-overlay'),play=document.getElementById('play-button'),err=document.getElementById('host-error');const timeout=<?=$timeout?>,healthUrl=<?=json_encode(app_url('api/stream-health.php'))?>;let index=0,loadTimer=null,loaded=false,attempted=[];function report(stream,event){fetch(healthUrl,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:<?=json_encode($token)?>,stream_id:stream.id,event_type:event})}).catch(()=>{});}function setErr(text,showRetry){err.innerHTML='';const span=document.createElement('span');span.textContent=text;err.appendChild(span);if(showRetry){const b=document.createElement('button');b.className='retry';b.textContent='Retry host';b.onclick=()=>tryHost(index);err.appendChild(b)}err.style.display='block'}function nextHost(reason){if(hosts[index]){report(hosts[index],reason);}index++;if(index<hosts.length){setErr('Host unavailable — switching to another host…',false);setTimeout(()=>tryHost(index),350)}else{loading.classList.add('hidden');setErr('All configured hosts failed to load.',true)}}function tryHost(i){if(!hosts.length)return;index=i;loaded=false;clearTimeout(loadTimer);err.style.display='none';loading.classList.remove('hidden');frame.src=hosts[i].url;loadTimer=setTimeout(()=>{if(!loaded)nextHost('timeout')},timeout)}frame.addEventListener('load',()=>{loaded=true;clearTimeout(loadTimer);loading.classList.add('hidden');overlay.classList.remove('hidden')});frame.addEventListener('error',()=>nextHost('load_error'));play.addEventListener('click',()=>{overlay.classList.add('hidden');try{frame.contentWindow.postMessage({type:'vep-play'},'*')}catch(e){}});window.addEventListener('message',e=>{if(e.data&&e.data.type==='vep-play-failed'&&hosts[index])nextHost('play_failed')});tryHost(0)})();</script></body></html>